mapper.select:
SELECT COUNT(*)
FROM exam_arrange
WHERE course_id = #{courseId}
  AND (semester_id <=> #{semesterId})

    AND id != #{excludeId}

SELECT e.id, c.name AS courseName, e.start_section AS startSection, e.end_section AS endSection
FROM exam_arrange e
LEFT JOIN course c ON e.course_id = c.course_id
WHERE e.room = #{room}
  AND e.exam_date = #{examDate}
  AND NOT (e.end_section < #{startSection} OR e.start_section > #{endSection})

    AND e.id != #{excludeId}

LIMIT 1

SELECT e.id, c.name AS courseName, e.room, e.start_section AS startSection, e.end_section AS endSection
FROM exam_arrange e
LEFT JOIN course c ON e.course_id = c.course_id
WHERE e.invigilator_uid = #{invigilatorUid}
  AND e.exam_date = #{examDate}
  AND NOT (e.end_section < #{startSection} OR e.start_section > #{endSection})

    AND e.id != #{excludeId}

LIMIT 1
